export async function checkRateLimit(ip: string, kv: KVNamespace, limit = 100): Promise<{ allowed: boolean; remaining: number }> {
  try {
    const current = Number(await kv.get(`rate:${ip}`)) || 0;
    if (current >= limit) return { allowed: false, remaining: 0 };
    await kv.put(`rate:${ip}`, String(current + 1), { expirationTtl: 60 });
    return { allowed: true, remaining: limit - current - 1 };
  } catch (err) {
    // Graceful degradation: fail-open if KV is temporarily unavailable
    console.warn('Rate limiter degraded, failing open:', err);
    return { allowed: true, remaining: 1 };
  }
}
